'Show_Previous_Dues_Line' => 'Zobrazit řádek Předchozí dluhy',
'Show_Previous_Dues_Line_Desc' => 'Zůstatek, který zákazník dlužil před tímto prodejem. Tiskne se pouze, je-li větší než nula.',
'Show_Net_Balance_Line' => 'Zobrazit řádek Čistý zůstatek',
'Show_Net_Balance_Line_Desc' => 'Předchozí dluhy plus to, co zbývá uhradit z tohoto prodeje. Tiskne se pouze, jsou-li předchozí dluhy větší než nula.',

'QZ_Tray_Printer' => 'QZ Tray (tiskárna na tomto počítači)',
'QZ_Printer_Name_Hint' => 'Název tiskárny, jak se zobrazuje na počítači se spuštěným QZ Tray. Ponechte prázdné pro použití výchozí tiskárny tohoto počítače. Kliknutím na ⟳ vyhledáte tiskárny.',
'QZ_Not_Running' => 'QZ Tray na tomto počítači neběží. Nainstalujte jej z qz.io, nechte jej spuštěný a po výzvě QZ tento web povolte.',
'Detect_Printers' => 'Vyhledat tiskárny',
'QZ_Download_Cert' => 'Stáhnout certifikát (override.crt)',
'QZ_Setup_Title' => 'Jak nastavit tisk přes QZ Tray (jednorázově, na každém počítači, který tiskne štítky)',
'QZ_Step_Install' => '1. Nainstalujte QZ Tray na tento počítač — stáhněte jej zdarma z qz.io, spusťte jej a nechte běžet (ve Windows je v oznamovací oblasti, v macOS na liště nabídek).',
'QZ_Step_Connect' => '2. Připojte tiskárnu štítků přes USB a ověřte, že je nainstalována v operačním systému (Windows: Nastavení > Tiskárny a skenery — macOS: Nastavení systému > Tiskárny a skenery).',
'QZ_Step_Detect' => '3. Kliknutím na tlačítko ⟳ vedle „Název tiskárny“ výše vyhledáte tiskárny na tomto počítači, poté vyberte svou tiskárnu štítků. Ponechte pole prázdné pro použití výchozí tiskárny počítače.',
'QZ_Step_Cert' => '4. Pro tisk bez vyskakovacího okna s oprávněním stáhněte níže uvedený certifikát a zkopírujte jej do instalační složky QZ Tray s názvem override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Poté QZ Tray ukončete a znovu spusťte.',
'QZ_Step_Test' => '5. Klikněte níže na „Vytisknout testovací štítek“. Pokud QZ Tray požádá o oprávnění, klikněte na Povolit — s nainstalovaným certifikátem se již znovu nezeptá.',
'QZ_Step_Save' => '6. Kliknutím na Odeslat tato nastavení uložte. Štítky ze stránky Tisk čárových kódů se nyní budou tisknout přímo na této tiskárně bez dialogu tisku prohlížeče.',
'QZ_Setup_Note' => 'QZ Tray běží na počítači, ze kterého prohlížíte, takže to funguje i tehdy, když je Stocky hostován na vzdáleném serveru. Každý počítač, který tiskne štítky, potřebuje nainstalovaný QZ Tray.',

