'PWA_Enabled' => 'Povolit instalovatelnou aplikaci',
'PWA_Enabled_Help' => 'Umožňuje prohlížečům nabídnout instalaci této aplikace na telefony, tablety a počítače a uchovává stránky v mezipaměti pro práci offline. Vypnutím se výzva k instalaci všude odstraní a mezipaměť se při další návštěvě vymaže.',
