'Label_Render_Mode' => 'Vykreslování štítku',
'Label_Render_Mode_Hint' => 'Způsob vykreslení štítku. Písma tiskárny jsou nejrychlejší a dávají nejostřejší čárový kód, ale tisknou pouze základní latinské znaky vlastním písmem tiskárny. Obrázek náhledu přesně reprodukuje váš design štítku — zvolené písmo, libovolný jazyk — stejně jako specializovaný software pro štítky.',
'Render_Native' => 'Písma tiskárny (nejrychlejší)',
'Render_Raster' => 'Obrázek náhledu (přesný design)',
'Label_Width_Mm' => 'Šířka štítku (mm)',
'Label_Height_Mm' => 'Výška štítku (mm)',
'Label_Size_Hint' => 'Fyzická velikost jedné nálepky na roli. Musí přesně odpovídat vloženým štítkům — nesprávná velikost způsobí, že tiskárna hledá mezeru na špatném místě a každý další štítek se tiskne více mimo pozici.',
'Calibrate_Labels' => 'Kalibrovat štítky',
'Calibrate_Labels_Hint' => 'Tiskárna posune několik štítků, aby změřila nálepku a mezeru. Spusťte jednou po vložení nové role nebo když se pozice tisku posouvají.',
'Calibration_Sent' => 'Kalibrace zahájena — tiskárna posune několik prázdných štítků, aby je změřila. Až se zastaví, proveďte zkušební tisk.',
'Label_Printer_Dpi' => 'Rozlišení tiskové hlavy',
'Label_Printer_Dpi_Hint' => 'Většina tiskáren štítků má 203 dpi. Nejste si jisti? Použijte níže tlačítko „Zjistit rozlišení“ — vytiskne odpověď.',
'Find_Resolution' => 'Zjistit rozlišení',
'Find_Resolution_Hint' => 'Vytiskne dva štítky označené 203 a 300. Správný ukazuje na nálepce celý obdélník s malým rovnoměrným okrajem na všech čtyřech stranách; nesprávnému chybí okraje nebo přesahuje na další nálepku.',
'Dpi_Test_Sent' => 'Tisknou se dva štítky označené 203 a 300. Správný ukazuje celý obdélník s malým rovnoměrným okrajem na všech čtyřech stranách — nastavte „Rozlišení tiskové hlavy“ na toto číslo a uložte.',
'Label_Offset_X' => 'Vodorovný posun (mm)',
'Label_Offset_X_Hint' => 'Posune tisk na nálepce do strany. Použijte, když je text na jednom okraji oříznut — např. 2.5, když je bílá nálepka vystředěna na širším podkladovém papíru. Upravujte po krocích 0.5.',
'Label_Offset_Y' => 'Svislý posun (mm)',
'Label_Offset_Y_Hint' => 'Posune tisk podél štítku. Zvyšte, když je horní část designu oříznutá nebo chybí; snižte, když začíná příliš nízko.',
'Feed_To_Tear' => 'Posunout k odtrhávací hraně',
'Feed_To_Tear_Hint' => 'Po každé úloze posune štítek k odtrhávací liště. Ponechte VYPNUTO, pokud se štítky tisknou posunuté dolů nebo rozdělené přes nálepky — mnoho tiskáren se před dalším štítkem nevrací zpět.',
