'Ord_Guide_Payment_Pending' => 'Dobírka, bankovní převod nebo jiná metoda s pozdější platbou. Potvrzením objednávky se vytvoří prodej jako Nezaplaceno, takže peníze zaznamenáte sami po jejich přijetí — viz kroky níže.',
'Ord_Guide_Payment_Failed' => 'Brána platbu zamítla nebo ji zákazník nedokončil. Objednávka se automaticky zruší.',
