'Ord_Guide_MarkPaid_Step2' => 'Otevřete Prodeje > Všechny prodeje a najděte daný prodej (stejný zákazník; stránka podrobností ukazuje online objednávku, ze které vznikl).',
'Ord_Guide_MarkPaid_Step3' => 'Otevřete nabídku akcí řádku a zvolte Vytvořit platbu.',
'Ord_Guide_MarkPaid_Step4' => 'Zadejte částku, platební metodu a datum a uložte. Prodej se podle částky sám přesune do stavu Částečně nebo Zaplaceno.',
'Ord_Guide_MarkPaid_Note' => 'Zde zobrazený stav platby nadále zaznamenává volbu při placení a zůstává beze změny. Účetním záznamem je prodej a z něj čerpají přehledy plateb a zisku. Pomocí Zobrazit platby u prodeje zkontrolujete nebo upravíte, co jste zadali.',
'Ord_Guide_Notes_Title' => 'Dobré vědět',
'Ord_Guide_Note_Warehouse' => 'Sklad, který vyberete při potvrzení, určuje, odkud se zásoby odeberou. Sklady, které nemohou pokrýt celou objednávku, jsou v seznamu označeny jako Vyprodáno.',
'Ord_Guide_Note_Preorder' => 'Předobjednané položky přeskakují kontrolu zásob, takže objednávku, která je obsahuje, lze potvrdit, i když množství ještě není skladem.',
'Ord_Guide_Note_Flagged' => 'Štítek Označeno znamená, že objednávka při placení spustila kontrolu podvodu. Najetím na štítek zobrazíte důvod; před potvrzením objednávku zkontrolujte.',
