// Variants guide drawer (product form).
'Guide' => 'Průvodce',
'Variants_Guide' => 'Průvodce variantami',
'VG_Intro' => 'Variabilní produkt se prodává jako několik variant. Sestavte je z možností (doporučeno) nebo jako jednoduchý seznam názvů. Každá varianta má vlastní kód, ceny, obrázek a zásoby.',
