'VG_Opt_Step5' => 'Klikněte na „Vygenerovat varianty“. Pro každou kombinaci se vytvoří jeden řádek a jeho název se sestaví automaticky, například „Červená / S“.',
'VG_Opt_Step6' => 'Na každém řádku zadejte náklady a cenu, nebo zadejte hodnotu do „Použít pro všechny“ a kliknutím na Náklady nebo Cena ji zkopírujte do všech řádků.',
'VG_Opt_Step7' => 'Kódy se generují automaticky. Zadejte vlastní nebo kliknutím na ikonu obnovení vygenerujte jiný.',
'VG_Opt_Step8' => 'Nepovinné: u možnosti zaškrtněte „Barevné vzorky“ a pro každou hodnotu vyberte barvu; obchod ji zobrazí jako barevnou tečku.',
'VG_Rows_Title' => 'Řádky variant',
'VG_Rows_Text' => 'Každý řádek má obrázek, kód, čárový kód, náklady, cenu, velkoobchodní cenu a minimální prodejní cenu. Při vytváření produktu můžete pro každou variantu zadat také počáteční zásoby v jednotlivých skladech. Štítek „Neúplné“ znamená, že řádku chybí hodnota jedné z možností.',
'VG_List_Title' => 'Režim jednoduchého seznamu',
'VG_List_Text' => 'Zadejte název varianty a stiskněte Enter (nebo klikněte na Přidat) pro přidání řádku, poté vyplňte jeho kód a ceny. Toto je klasické chování a zůstává dostupné pro stávající produkty.',
'VG_Edit_Title' => 'Pozdější úpravy',
'VG_Edit_1' => 'Přidejte hodnotu a klikněte na „Vygenerovat varianty“: přidají se pouze chybějící kombinace. Stávající řádky si ponechají své kódy, ceny a historii.',
'VG_Edit_2' => 'Odebráním hodnoty nebo možnosti se odeberou řádky, které ji používají. Již uložené řádky budou po potvrzení smazány při uložení produktu.',
'VG_Edit_3' => 'Variantu, která má stále zásoby, nelze odebrat. Nejprve její zásoby upravte nebo převeďte.',
