'Set_Qb_Synced_N_Selected' => 'Synchronizováno {n} vybraných',
'Set_Subscription_Reminder' => 'Připomínka předplatného',
'Upd_Note_Code_Changes_Lost' => 'Poznámka 1: Pokud jste v kódu provedli ruční změny, budou vaše změny ztraceny.',
'Upd_Manual_Steps_Intro' => 'Pro aktualizaci aplikace postupujte podle těchto kroků',
'Upd_Note_Permission_Only' => 'Poznámka 2: systém může aktualizovat pouze administrátor nebo uživatel s oprávněním „{perm}“',
'Upd_Manual_Step_Backup_Db' => 'Zálohujte databázi. Přejděte do {backup}, klikněte na Vygenerovat zálohu — najdete ji v {path} — nebo exportujte databázi z PhpMyAdmin a uložte ji do počítače.',
'Upd_Manual_Step_Backup_Files' => 'Před aktualizací zálohujte soubory.',
'Upd_Manual_Step_Download' => 'Stáhněte nejnovější verzi ze svého účtu CodeCanyon a rozbalte ji.',
'Upd_Manual_Step_Remove' => 'Odstraňte předchozí soubory {except}:',
'Upd_Except' => 'kromě',
'Upd_File_Label' => 'soubor: {name}',
'Upd_Folder_Label' => 'složka: {name}',
'Upd_Manual_Step_Reupload' => 'Znovu nahrajte soubory a složky z nové aktualizace, {except} stejných tří cest uvedených výše.',
'Upd_Manual_Step_Visit' => 'Pro aktualizaci databáze navštivte {url}.',
'Upd_Manual_Step_Clear_Cache' => 'Důkladně vymažte mezipaměť prohlížeče.',
'Upd_Manual_Step_Done' => 'Hotovo! Užijte si aktualizovanou aplikaci.',
'Upd_Note_Blank_Pages' => 'Poznámka: Pokud se některé stránky nenačítají nebo jsou prázdné, ujistěte se, že jste vymazali mezipaměť prohlížeče.',
'Upd_Guide_Before_Title' => '1. Před aktualizací',
'Upd_Guide_Before_Download' => 'Stáhněte {package} aplikace ze svého účtu CodeCanyon ({path}). Nerozbalujte jej — aktualizátor potřebuje ZIP přesně tak, jak byl stažen.',
'Upd_Latest_Full_Zip' => 'nejnovější úplný balíček ZIP',
'Upd_Guide_Before_Admin' => 'Ujistěte se, že jste přihlášeni jako administrátor s oprávněním {perm}. Nikdo jiný aktualizátor nevidí ani nemůže spustit.',
'Upd_Guide_Before_Quiet' => 'Vyberte klidnou chvíli: během aktualizace se aplikace na krátkou dobu přepne do režimu údržby a ostatní uživatelé nebudou mít přístup.',
'Upd_Guide_Before_No_Manual' => 'Ručně zálohovat, rozbalovat soubory, spouštět příkazy, upravovat konfigurační soubory ani zasahovat do databáze {not} potřeba — aktualizátor to vše provede automaticky. (Dodatečná ruční záloha samozřejmě nikdy neuškodí.)',
'Upd_Not' => 'není',
'Upd_Guide_Code_Overwritten' => 'Pokud jste kód aplikace ručně upravili, aktualizace vaše změny přepíše. Vaše data, nahrané soubory, nastavení a .env jsou vždy zachovány.',
'Upd_Guide_Running_Title' => '2. Spuštění aktualizace',
'Upd_Guide_Run_Open' => 'Otevřete {path} (tuto stránku) a zůstaňte na kartě {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: klikněte nebo přetáhněte stažený balíček do pole pro nahrání. Velké soubory se nahrávají po malých částech, takže to funguje i na sdíleném hostingu s nízkými limity nahrávání. Kontrolní součet chrání před poškozeným nebo neúplným nahráním.',
'Upd_Upload_The_Zip' => 'Nahrajte ZIP',
'Upd_Guide_Run_Validation' => '{auto} po nahrání (můžete ji znovu spustit tlačítkem {button}). Systém kontroluje: integritu ZIP, strukturu a úplnost balíčku, kompatibilitu verzí (přechod na nižší verzi je odmítnut), požadovanou verzi PHP a rozšíření, oprávnění souborů, volné místo na disku, připojení k databázi, konfiguraci a to, že neprobíhá jiná aktualizace.',
'Upd_Validation_Runs_Automatically' => 'Ověření proběhne automaticky',
'Upd_Guide_Run_Review' => 'Zkontrolujte panel {panel}. Tlačítko {button} se zobrazí, pouze když projdou všechny kritické kontroly. Pokud kontrola selže, zpráva vám přesně řekne, co opravit.',
'Upd_Guide_Run_Click' => 'Klikněte na {button} a potvrďte. Poté jednoduše {keep} a sledujte ukazatel průběhu. Systém v tomto pořadí provede:',
'Upd_Keep_Page_Open' => 'nechte tuto stránku otevřenou',
'Upd_Guide_Phase_Backup' => '{label} — vytvoří se a {verified} úplný výpis databáze, ZIP všech souborů aplikace, které může aktualizace změnit, a kopie {env}. Vašich nahraných souborů ({images}) a {storage} se aktualizace nikdy nedotkne, proto se nearchivují. Pokud zálohu nelze vytvořit, aktualizace se zde zastaví a nic se nezmění.',
'Upd_Verified' => 'ověří',
'Upd_Guide_Phase_Prepare' => '{label} — nová verze se rozbalí do přípravné oblasti a znovu se ověří. Živá aplikace zůstává stále nedotčena.',
'Upd_Guide_Phase_Maintenance' => '{label} — zapne se režim údržby; návštěvníci uvidí přátelskou obrazovku „Hned jsme zpět“.',
'Upd_Guide_Phase_Files' => '{label} — nové soubory se téměř okamžitě přepnou; staré soubory se uchovají stranou pro návrat zpět. Chráněné cesty ({env}, {storage}, {images}) se nikdy nenahrazují.',
'Upd_Guide_Phase_Database' => '{label} — spustí se migrace, poté se obnoví oprávnění, překlady a šablony.',
'Upd_Guide_Phase_Cache' => '{label} — všechny mezipaměti se vymažou a znovu sestaví.',
'Upd_Guide_Phase_Verify' => '{label} — kontroly stavu potvrdí, že se nová verze spustí, databáze funguje, všechny migrace proběhly a konfigurace je platná.',
'Upd_Guide_Phase_Done' => '{label} — režim údržby se ukončí a dočasné soubory se vyčistí.',
'Upd_Guide_Run_Success' => 'Jakmile uvidíte {success}, klikněte na {reload} a důkladně obnovte prohlížeč ({keys}), aby se načetly nové soubory administrace.',
'Upd_Update_Successful_Short' => 'Aktualizace proběhla úspěšně',
'Upd_Guide_No_Internet' => 'Během aktualizace není potřeba připojení k internetu — vše pochází z nahraného ZIP. Ztráta připojení nebo zavření prohlížeče aktualizaci NEPŘERUŠÍ: server si přesně pamatuje, kde skončil.',
'Upd_Guide_Wrong_Title' => '3. Pokud se něco pokazí',
'Upd_Guide_Wrong_Rollback' => '{label} — pokud cokoli selže poté, co se začaly měnit soubory (chyba rozbalení, selhání migrace, neúspěšná kontrola stavu, plný disk, …), systém automaticky obnoví předchozí soubory a databázi z ověřené zálohy, ukončí režim údržby a nahlásí {message}. Skončíte přesně tam, kde jste začali.',
'Upd_Automatic_Rollback' => 'Automatický návrat zpět',
'Upd_Failed_Previous_Restored' => 'Aktualizace selhala — obnovena předchozí verze',
'Upd_Guide_Wrong_Interrupted' => '{label} (restart serveru, vypršení časového limitu, zavřený prohlížeč, výpadek napájení) — po opětovném otevření této stránky nabídne červený banner dvě bezpečné volby: {resume} (pokračuje přesně od kroku, kde se zastavila) nebo {rollback} (obnoví předchozí verzi ze zálohy).',
'Upd_Interrupted_Update' => 'Přerušená aktualizace',
'Upd_Guide_Wrong_Unreachable' => '{label} — použijte samostatnou {console} na adrese {path}. Funguje i v době, kdy je web v režimu údržby nebo jsou soubory administrace poškozené, a nabízí stejné akce Pokračovat / Vrátit zpět. Na spodní straně obrazovky údržby je také nenápadný odkaz „Přístup administrátora“.',
'Upd_Admin_Unreachable' => 'Administrace nedostupná',
'Upd_Recovery_Console' => 'konzoli pro obnovu',
'Upd_Guide_Wrong_Locked_Out' => '{label} — během aktualizace tato stránka zobrazuje {link}. Uložte si jej, pokud se budete potřebovat vrátit (například po vypršení relace); umožní vám projít obrazovkou údržby, abyste se mohli znovu přihlásit.',
'Upd_Locked_Out_Maintenance' => 'Zablokováno režimem údržby',
'Upd_Bypass_Link' => 'obcházecí odkaz',
'Upd_Guide_Wrong_Concurrent' => '{label} — uvidí {message} Současně může probíhat vždy jen jedna aktualizace.',
'Upd_Another_Admin_Updating' => 'Jiný administrátor se pokusí aktualizovat současně',
'Upd_Guide_Backups_Title' => '4. Zálohy a obnovení',
'Upd_Guide_Backups_Created' => 'Každá aktualizace vytvoří zálohu {before} na cokoli sáhne: všechny soubory aplikace, které může aktualizace nahradit, kopii {env} a úplný výpis databáze. Nahrané soubory a {storage} aktualizace nikdy nemění, a proto nejsou součástí zálohy — zálohujte si je sami. Zálohy jsou uloženy v {path} a nikdy nejsou přístupné z webu.',
'Upd_Before' => 'dříve, než',
'Upd_Guide_Backups_Panel' => 'Panel {panel} na kartě {tab} je uvádí s datem, verzí a velikostí. Odtud můžete {restore} jakoukoli úplnou zálohu (soubory + databáze — nejprve se pořídí bezpečnostní kopie aktuální databáze) nebo {delete} staré.',
'Upd_Restore_Verb' => 'obnovit',
'Upd_Delete_Verb' => 'smazat',
'Upd_Guide_Backups_Retention' => 'Pomocí {keep} zvolte, kolik záloh se má uchovávat; starší se po každé úspěšné aktualizaci automaticky odstraní. Jedinou zbývající úplnou zálohu nelze nikdy smazat — vždy máte cestu zpět.',
'Upd_Guide_Manual_Title' => '5. Ruční aktualizace (záložní postup)',
'Upd_Guide_Manual_Text' => 'Pokud dáváte přednost ruční aktualizaci nebo nelze na vašem serveru použít nahrávání, postupujte podle podrobných pokynů na kartě {tab} této stránky.',
'Upd_Guide_Clear_Cache_First' => 'Pokud stránky po jakékoli aktualizaci vypadají rozbitě nebo jsou prázdné, nejprve vymažte mezipaměť prohlížeče — téměř vždy je to příčinou.',
'Upd_Restore_Backup_Confirm' => 'Obnovit tuto zálohu? Aktuální soubory a aktuální databáze budou nahrazeny zálohou. Nejprve se pořídí bezpečnostní kopie aktuální databáze. (v{version} — {date})',
'Woo_Guide_Lead' => 'Jak se obchod WooCommerce udržuje v souladu s ERP. Níže uvedené řádky cronu jsou sestaveny pro tento server, takže je lze zkopírovat přímo na něj.',
'Woo_Guide_Ways_Note' => 'Na rozdíl od Shopify WooCommerce do ERP sám nic neposílá — není zde přijímač webhooků, takže vše, co přichází {in}, dorazí podle plánu. Okamžité může být pouze odesílání zásob {out}.',
'Woo_In' => 'dovnitř',
'Woo_Out' => 'ven',
'Woo_Guide_Both_Ways_Title' => 'Oba směry nejprve potřebují toto',
'Woo_Api_Keys' => 'Klíče API',
'Woo_Guide_Api_Keys_Text' => '{path}, oprávnění {perm}. Zkopírujte consumer key a secret na kartu {settings} spolu s URL obchodu — adresou vašeho webu bez koncového lomítka, např. {example}.',
'Woo_Credentials_Saved' => 'přihlašovací údaje uloženy',
'Woo_Not_Configured_Yet' => 'zatím nenastaveno',
'Woo_Guide_Wp_App_Password_Title' => 'Heslo aplikace WordPress (volitelné)',
'Woo_Guide_Wp_App_Password_Text' => 'Používá se pouze pro obrázky produktů. API WooCommerce přenáší produkty, zásoby, kategorie, značky, zákazníky a objednávky; API WordPressu prohledává knihovnu médií a nahrává obrázek, který tam ještě není.',
'Woo_Guide_Wp_App_Password_Note' => 'Použijte uživatele WordPressu, který může spravovat média, a vytvořte heslo v {path}. Ponechte obě pole prázdná a vše se bude synchronizovat i nadále — pouze se vynechá připojování obrázků.',
'Woo_Guide_Pick_Way_Title' => 'Pak zvolte, jak se má udržovat v souladu',
'Woo_Right_Away' => 'Okamžitě',
'Woo_Stock_Live' => 'zásoby živě',
'Woo_Stock_Not_Live' => 'zásoby ne živě',
'Woo_Guide_Realtime_Lead' => 'Pouze jeden směr: zásoby a produkty odcházející z ERP. Objednávky a úpravy produktů provedené ve WooCommerce stále přicházejí podle plánu — viz druhá karta.',
'Woo_Push_Stock_On_Change' => 'Odeslat zásoby ve chvíli, kdy se změní',
'Woo_Setting_People_Miss' => 'Toto nastavení lidé přehlížejí',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Prodej v POS {not} do WooCommerce sám. Pokud je vypnuto, obchod se o něm dozví až při další synchronizaci zásob — standardně za hodinu — a v tomto okně může prodat kus, který jste již prodali na pokladně.',
'Woo_Does_Not' => 'se nedostane',
'Woo_Guide_Tick_Instant' => 'Zaškrtněte {option} na kartě {settings}. To je celé nastavení — žádný worker, žádný cron. Každý prodej, vratka, úprava, převod a přijatý nákup pak odešle aktualizaci pouze těchto produktů hned po uložení prodeje a prodej o dvaceti řádcích stojí jedno odeslání, ne dvacet. Pokladna na to nikdy nečeká.',
'Woo_Currently' => 'Aktuálně:',
'Woo_Instant_On_Text' => 'zapnuto — zásoby odesílány při změně',
'Woo_Instant_Off_Text' => 'vypnuto — zásoby pouze podle plánu',
'Woo_Guide_Instant_Note' => 'Odesílají se pouze produkty již propojené s WooCommerce — produkt, který nikdy nebyl synchronizován, nemá v obchodě co opravit. Variabilní produkty jdou přes svého rodiče a kombinace se odešle znovu, když se pohne kterákoli z jejích součástí. Hromadné operace (smazání produktu, vynulování skladu) zapisují zásoby bez vyvolání události, což je jeden z důvodů ponechat i hodinovou synchronizaci zásob.',
'Woo_Push_Products_On_Save' => 'Odeslat produkty ve chvíli, kdy jsou uloženy',
'Woo_Guide_Tick_Auto_Products' => 'Zaškrtněte {option} na kartě {settings} a produkt vytvořený, upravený nebo duplikovaný ve Stocky se odešle do WooCommerce hned po uložení — údaje, cena, varianty a obrázky, pak jeho zásoby. Nový produkt se v obchodě vytvoří okamžitě, místo aby čekal na noční synchronizaci produktů.',
'Woo_On' => 'zap.',
'Woo_Off' => 'vyp.',
'Woo_Guide_Bulk_Imports_Note' => 'Hromadné importy se neodesílají jednotlivě — po importu spusťte synchronizaci produktů. Nejprve synchronizujte kategorie a značky, aby odeslaný produkt skončil ve správné kategorii.',
'Woo_Nothing_Else_To_Install' => 'Nic dalšího k instalaci',
'Woo_Guide_Same_Process' => 'Žádný worker fronty, žádný záznam cronu. Odeslání běží ve stejném procesu, který obsloužil prodej, {after} odeslání odpovědi, takže pokladna nikdy nečeká na WooCommerce. Odeslání se nikdy nepřekrývají: změny provedené během běžícího odeslání na něj počkají a odejdou hned po něm.',
'Woo_After' => 'až po',
'Woo_Guide_Shop_Stops_Answering' => 'Obchod, který přestane odpovídat, se vzdá po osmi sekundách a odesílání se na pět minut pozastaví, aby na něj nečekal každý prodej znovu; změny, které mezitím přišly, odejdou s prvním odesláním po pauze a hodinová synchronizace zásob vše dožene tak jako tak. Každá pauza se zaznamená na kartě Protokoly.',
'Woo_Guide_Artisan_Exception' => 'Jedna výjimka: změna zásob provedená příkazem artisan nemá odpověď, po které by mohla přijít, takže se místo toho řadí do fronty {queue}. Chcete-li, aby i tyto odcházely bez prodlení, zpracovávejte tuto frontu:',
'Woo_Cron_Line_Copied' => 'Řádek cronu zkopírován',
'Woo_Command_Copied' => 'Příkaz zkopírován',
'Woo_Guide_Not_Woo_Queue' => 'Záměrně ne fronta {queue}: ta nese hodiny trvající dávky katalogu a okamžité odeslání zařazené za jednu z nich by nebylo okamžité.',
'Woo_On_A_Schedule' => 'Podle plánu',
'Woo_Guide_Scheduled_Lead' => 'Vše se v obou směrech co čas znovu kontroluje. Takto se objednávky dostávají do ERP, takto se publikuje katalog a takto se opraví vše, co rychlá cesta vynechala. Každá úloha má vlastní záznam cronu, takže spouštíte jen to, co chcete.',
'Woo_Guide_Sync_Drains_Queue' => '{command} během běhu zpracovává vlastní frontu, takže tyto řádky nepotřebují samostatný worker. Ve Windows použijte Plánovač úloh s programem {program} a stejnými argumenty, spouštěným v {path}.',
'Woo_Or_No_Cron' => 'Nebo úplně bez cronu',
'Woo_Guide_No_Cron_Text' => 'Každá karta zde synchronizuje na vyžádání a ruční synchronizace zpracovává vlastní dávky, dokud je stránka otevřená — malý obchod tak může běžet zcela bez záznamu cronu. Přijdete však o vše, co se děje, když se nikdo nedívá: objednávky dorazí, jen když někdo stiskne tlačítko.',
'Woo_Commands_Worth_Knowing' => 'Užitečné příkazy',
'Woo_Worth_Knowing' => 'Dobré vědět',
'Woo_Guide_Changing_Url_Clears' => 'Změna URL obchodu nebo klíčů API vymaže všechna mapování — produkty, kategorie, značky i zákazníci se znovu synchronizují do nového obchodu.',
'Woo_Guide_Keep_Skus' => 'Udržujte SKU mezi Stocky a WooCommerce konzistentní: to zabraňuje duplicitám a díky tomu je opětovné propojení bezpečné.',
'Woo_Guide_Stock_Total' => 'Zásoby publikované do Woo jsou {total}, nikoli stav jednoho skladu.',
'Woo_Total_Across_Warehouses' => 'celkový stav napříč všemi sklady',
'Woo_Guide_Full_Reference' => 'Úplná reference — všechny rozsahy, chování fronty a seznam řešení problémů — je v {file}.',
'Woo_Way_Covers' => 'Zahrnuje',
'Woo_Way_Covers_Realtime' => 'Pouze zásoby odcházející z ERP — prodej v POS, vratka, úprava, přijatý nákup',
'Woo_Way_Covers_Scheduled' => 'Vše v obou směrech: objednávky a změny produktů dovnitř, katalog a zásoby ven',
'Woo_Way_Speed' => 'Rychlost',
'Woo_Way_Seconds' => 'Sekundy',
'Woo_Way_Speed_Scheduled' => 'Cokoli zadáte do záznamu cronu (zásoby každou hodinu, objednávky každých 15 min)',
'Woo_Way_Needs' => 'Potřebuje',
'Woo_Way_Needs_Realtime' => 'Nic — jen nastavení',
'Woo_Way_Needs_Scheduled' => 'Záznam cronu pro každou úlohu — nebo nic, pokud synchronizujete ručně',
'Woo_Way_Switched_On_At' => 'Zapíná se v',
'Woo_Way_Cron_Entries_Below' => 'Níže uvedené záznamy cronu',
'Woo_Cron_Orders' => 'Objednávky každých 15 minut — pouze ty změněné od posledního běhu.',
'Woo_Cron_Products_Pull' => 'Změny produktů z obchodu, každou noc ve 03:00.',
'Woo_Cron_Customers' => 'Zákazníci, každou noc ve 03:30.',
'Woo_Cron_Stock' => 'Zásoby každou hodinu — záchranná síť pod okamžitým odesíláním a jediná synchronizace zásob bez něj.',
'Woo_Cron_Products_Push' => 'Dosud nepropojené produkty, každou noc ve 02:00. Stávající produkty se nepřepisují.',
'Woo_Cmd_Stock' => 'Odeslat nyní zásoby všech propojených produktů.',
'Woo_Cmd_Products_Unsynced' => 'Publikovat produkty, které ještě nemají ID WooCommerce.',
'Woo_Cmd_Orders' => 'Importovat objednávky změněné od posledního běhu.',
'Woo_Cmd_Orders_Full' => 'Znovu prohledat všechny objednávky místo pouze nedávných změn.',
'Woo_Cmd_Pull' => 'Vše příchozí najednou: produkty, objednávky, zákazníci.',
'Woo_Guide_Page_Title' => 'Průvodce WooCommerce',
'Woo_Guide_Page_Subtitle' => 'Připojení obchodu, co běží samo a záznamy cronu pro tento server',
