'Xero_Push_Invoices_Desc' => 'Vytvoří jednu fakturu AUTHORISED na každý prodej (číslo faktury = Ref prodeje) s řádky prodeje a řádky dopravy, slevy a daně, aby celková částka v Xero odpovídala celkové částce prodeje. Prodeje již v Xero se přeskakují — faktury se nikdy neupravují. Chybějící kontakty se vytvoří průběžně.',
