'Jumia_Push_Prices_Stock_Title' => 'Odeslat ceny a zásoby do Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Odešle aktuální cenu a množství pro každý produkt (a variantu), jehož SKU odpovídá {sku} nabídky Jumia. Aktualizace se odesílají jako feedy Seller Center a uplatňují se asynchronně — ID feedu se zaznamená na kartě Protokoly a odmítnutí jednotlivých položek se zobrazí na obrazovce stavu feedu v Seller Center.',
'Jumia_Push_Prices_Stock' => 'Odeslat ceny a zásoby',
'Jumia_Pull_Orders_Desc' => 'Importuje objednávky z tržiště jako prodeje (reference jako {ref}), spárované s vašimi produkty podle Seller SKU. Již importované a zrušené objednávky se přeskakují, takže pravidelné načítání je bezpečné. Platby se označí jako zaplacené pouze u doručených objednávek (u Jumia převažuje dobírka).',
'Jumia_Guide_1' => 'V Jumia {sellerCenter} otevřete {menu} a vygenerujte klíč API.',
'Jumia_Guide_2' => 'Zadejte URL API své země (např. {ng} pro Nigérii, {ke} pro Keňu, {eg} pro Egypt), e-mail účtu Seller Center a klíč — poté spusťte {test}.',
'Jumia_Guide_3' => 'Ujistěte se, že {sku} každé nabídky Jumia se rovná kódu produktu Stocky — to je identita používaná pro odesílání zásob i párování objednávek.',
'Jumia_Guide_4' => 'Po změnách zásob odešlete ceny a zásoby; objednávky načítejte pravidelně (Jumia v tomto API nemá webhooky).',
