'Mailchimp_With_Email' => 'S e-mailem',
'Mailchimp_Push_Desc' => 'Vloží nebo aktualizuje každého zákazníka s e-mailovou adresou ve vybraném publiku (včetně jména a telefonu). Stávající členové si ponechají stav odběru — nikdo, kdo se odhlásil, nebude znovu přihlášen. Zákazníci bez e-mailu jsou vynecháni.',
