'Shopify_Stock_Lag_Desc' => 'Prodej na pokladně zůstane do té doby pro obchod neviditelný — až {n} minut, takže poslední kus lze stále prodat online dvakrát. Zapněte {setting} a každý prodej, vratka i úprava se místo toho odešle během několika sekund.',
'Shopify_Turn_It_On' => 'Zapnout',
