'Shopify_Hook_Msg_Token' => 'Klikněte níže na „Registrovat webhooky“ a vložte API secret key aplikace do nastavení obchodu jako podpisový klíč.',
'Shopify_Hook_Note_Register' => 'Registrace vytvoří odběry v Shopify a automaticky je nasměruje na tuto adresu. Nepřidávejte ji ručně v Shopify → Settings → Notifications → Webhooks: ty jsou podepsány jiným klíčem a každé doručení by bylo odmítnuto.',
'Shopify_Hook_Verified_Client' => 'Doručení se ověřují pomocí client secret aplikace, který je již uložen.',
'Shopify_Hook_Signature_Required' => 'Doručení bez platného podpisu jsou odmítnuta, takže klíč musí být nastaven dříve, než webhooky cokoli udělají.',
'Shopify_Hook_Retries' => 'Shopify opakuje, dokud nedostane 2xx, a každé doručení se zaznamená jednou — opakovaná událost nic nezpůsobí, nevznikne duplicitní objednávka.',
'Shopify_No_Signing_Secret' => 'Není uložen podpisový klíč',
