'Shopify_Could_Not_Remove_Sub' => 'Tento odběr nelze odstranit',
'Shopify_Could_Not_Load_Store' => 'Tento obchod nelze načíst',
'Shopify_G_Lead_Store' => 'Co tento obchod potřebuje, aby se udržoval v souladu. Vše zde je specifické pro tento obchod — cesty a ID jsou skutečné, takže příkazy lze zkopírovat přímo na server.',
'Shopify_G_Lead_Generic' => 'Jak se obchod Shopify udržuje v souladu s ERP. Výše vyberte obchod a uvidíte jeho vlastní stav, nebo si to přečtěte tak, jak to je — řádek cronu a URL webhooku jsou stejné, ať připojíte jakýkoli obchod.',
'Shopify_G_Ways_Note' => 'Většina obchodů používá obojí: první udržuje obchod aktuální minutu po minutě, druhé zachytí vše, co první vynechalo — webhook, který nikdy nedorazil, úpravu provedenou přímo v administraci Shopify, noc, kdy byl web mimo provoz.',
'Shopify_G_Both_Need' => 'Oba směry nejprve potřebují toto',
'Shopify_G_Credentials' => 'Přihlašovací údaje Shopify',
'Shopify_G_Cred_Intro' => 'Od ledna 2026 již Shopify nevytváří vlastní aplikace v administraci, proto existují dva druhy připojení:',
'Shopify_G_Cred_DevDash' => '{app} (jakýkoli nyní připojený obchod) — {path}. Udělte rozsahy Admin API pro to, co tento obchod synchronizuje, nainstalujte aplikaci do obchodu a poté zkopírujte {clientId} a {clientSecret} ze stránky Settings aplikace do {where}. ERP je samo vymění za přístupový token a obnoví jej před vypršením každých 24 hodin. Client secret také podepisuje webhooky, takže nic dalšího není potřeba. Aplikace a obchod musí být ve stejné organizaci Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'Aplikace Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (vytvořená v administraci před rokem 2026) — funguje beze změny se svým {token} ({prefix}) a svým {secret} jako podpisovým klíčem webhooků. Nejde o stejnou hodnotu jako token a jejich záměna je obvyklým důvodem, proč jsou webhooky odmítány.',
'Shopify_G_Legacy_App' => 'Starší vlastní aplikace',
'Shopify_G_API_Secret_Key' => 'Tajný klíč API',
'Shopify_G_Stored' => 'uloženo',
'Shopify_G_Missing_Refused' => 'chybí — doručení budou odmítnuta',
'Shopify_G_Where_Data_Desc' => '{path} Sklad ERP, jehož zásoby tento obchod prodává, a umístění Shopify, kam se tyto zásoby zapisují. Synchronizace zásob i import objednávek bez nich odmítnou běžet.',
'Shopify_G_Currently' => 'Aktuálně: sklad {warehouse}, umístění {location}',
'Shopify_G_Not_Set_Lower' => 'nenastaveno',
'Shopify_G_Ready' => 'připraveno',
'Shopify_G_Incomplete' => 'neúplné',
'Shopify_G_Manual_Syncs' => 'Synchronizace spouštěné ručně',
'Shopify_G_Manual_Desc' => 'Synchronizace spuštěná z {centre} odpoví okamžitě a běží na pozadí v krátkých úsecích, z nichž každý pokračuje tam, kde předchozí skončil. Velký katalog tak nikdy není přerušen v půlce hostingem, který ukončuje dlouhé webové požadavky (LiteSpeed, nginx, load balancer), a zavření stránky jej nezastaví. Worker pro to je jeden další řádek cronu:',
'Shopify_G_Cron_Copied' => 'Řádek cronu zkopírován',
'Shopify_G_Manual_Note' => 'Bez něj se synchronizace stále dokončí, ale pouze dokud zůstane stránka Centrum synchronizace otevřená: když žádný worker běh během několika sekund nepřevezme, stránka jej provede sama, jeden krátký požadavek za druhým. Ve Windows použijte Plánovač úloh každou minutu: program {program}, argumenty {args}, spouštěno v {dir}.',
'Shopify_G_Then_Pick' => 'Pak zvolte, jak se má udržovat v souladu',
'Shopify_G_Right_Away' => 'Okamžitě',
'Shopify_G_Stock_Live' => 'zásoby živě',
'Shopify_G_Stock_Not_Live' => 'zásoby ne živě',
'Shopify_G_Realtime_Lead' => 'Každá změna se odešle, jakmile nastane, během několika sekund. Dvě poloviny se samostatnými přepínači: {webhooks} přinášejí vlastní události obchodu dovnitř a {push} odesílá zásoby ven.',
'Shopify_G_Webhooks_Lower' => 'webhooky',
'Shopify_G_Instant_Push_Lower' => 'okamžité odesílání zásob',
'Shopify_G_Webhooks_In' => 'Webhooky — obchod → ERP',
'Shopify_G_Webhooks_Desc' => 'Objednávky, změny stavu objednávek a úpravy produktů, zákazníků a zásob provedené v Shopify. Otevřete obchod a stiskněte {button} na jeho {tab} — lze bezpečně stisknout dvakrát. Shopify odesílá na:',
'Shopify_G_Webhooks_Tab' => 'kartě Webhooky',
'Shopify_G_Webhooks_Note' => 'Adresa musí být dosažitelná z internetu přes HTTPS — Shopify nedoručuje na {localhost} ani doménu {test}. Každé doručení se zaznamená jednou, takže opakování Shopify nemohou vytvořit duplicitní objednávku, a neúspěšné doručení lze přehrát znovu. Doručení jsou odmítána, dokud není uložen podpisový klíč z kroku 1.',
'Shopify_G_Instant_Out' => 'Okamžité odesílání zásob — ERP → obchod',
'Shopify_G_Setting_Missed' => 'Toto nastavení lidé přehlížejí',
'Shopify_G_Pos_Not_Auto' => 'Prodej v POS {not} do Shopify předán automaticky. Pokud je vypnuto, obchod se o něm dozví až při dalším kroku odeslání zásob — a v tomto okně může prodat kus, který jste již prodali na pokladně.',
'Shopify_G_Not' => 'není',
'Shopify_G_Tick_Push' => 'Zaškrtněte {setting} v {where}. To je celé nastavení — žádný worker, žádný cron. Každý prodej, vratka a úprava pak odešle aktualizaci pouze těchto produktů hned po uložení prodeje a prodej o dvaceti řádcích stojí jedno odeslání, ne dvacet. Pokladna na to nikdy nečeká.',
'Shopify_G_This_Store' => 'Tento obchod:',
'Shopify_G_Push_On' => 'zapnuto — zásoby odesílány při změně',
'Shopify_G_Push_Off' => 'vypnuto — zásoby pouze podle plánu',
'Shopify_G_Push_Note' => 'Odesílají se pouze produkty, které již mají mapování Shopify, a pouze pohyby ve skladu tohoto obchodu. Hromadné operace — smazání produktu, vynulování skladu — zapisují zásoby bez vyvolání události, což je jeden z důvodů ponechat i plánovaný krok zásob.',
'Shopify_G_Nothing_Install' => 'Nic dalšího k instalaci',
'Shopify_G_No_Worker_Note' => 'Žádná z polovin nepotřebuje worker fronty ani záznam cronu. Příchozí webhook se zpracuje v požadavku, který Shopify provede; odchozí odeslání zásob běží ve stejném procesu, který obsloužil prodej, {after} odeslání odpovědi — takže pokladna nikdy nečeká na Shopify a obchod, který přestane odpovídat, se vzdá po deseti sekundách a přenechá se dalšímu plánovanému odeslání zásob.',
'Shopify_G_After' => 'až po',
'Shopify_G_Artisan_Note' => 'Jedna výjimka: změna zásob provedená příkazem artisan nemá odpověď, po které by mohla přijít, takže se místo toho řadí do fronty {queue}. Chcete-li, aby i tyto odcházely bez prodlení, zpracovávejte tuto frontu:',
'Shopify_G_On_Schedule' => 'Podle plánu',
'Shopify_G_On_Lower' => 'zap.',
'Shopify_G_Off_Lower' => 'vyp.',
'Shopify_G_Scheduled_Lead' => 'Vše se v obou směrech co čas znovu kontroluje. Pomalejší než v reálném čase, ale právě to odesílá zásoby u obchodů, které nepoužívají okamžité odesílání, zachytí zmeškaný webhook a je jediným způsobem, jak přenést celý katalog.',
'Shopify_G_Cron_Entry' => 'Záznam cronu',
'Shopify_G_Cron_Entry_Desc' => 'Bez něj nic plánovaného neběží. Jeden řádek, pouze pro tento modul — přidejte jej vedle všeho ostatního, co jste se rozhodli plánovat:',
'Shopify_G_Cron_Note' => 'Každých pět minut je nejjemnější rozlišení, které plán může použít, protože pět minut je nejkratší interval kroku. Hrubší záznam se jednoduše stane spodní hranicí — s {example} se krok nastavený na 5 minut spustí každých 15. Ve Windows použijte Plánovač úloh: program {program}, argumenty {args}, spouštěno v {dir}.',
'Shopify_G_Switch_On_Plan' => 'Zapněte jej a zvolte plán',
'Shopify_G_Plan_Desc' => '{where} Přepínač rozhoduje, zda cron smí vůbec jednat; plán rozhoduje, co dělá. Jeden {step} představuje jednu entitu v jednom směru s vlastním intervalem — {first}, {second}. Výchozí interval se použije pro každý krok, který ponechá vlastní pole prázdné.',
'Shopify_G_Step_Lower' => 'krok',
'Shopify_G_Plan_Note' => 'Ponechte plán prázdný a obchod bude načítat objednávky a odesílat zásoby ve výchozím intervalu, což chce většina obchodů. Objednávky se pouze načítají: Shopify je místo, kde je zákazník zadává.',
'Shopify_G_Schedule_On' => 'plán zapnut',
'Shopify_G_Schedule_Off' => 'plán vypnut — pouze ručně',
'Shopify_G_When_Step_Runs' => 'Kdy krok skutečně proběhne',
'Shopify_G_When_Note' => 'Krok je na řadě, když se tentýž krok naposledy {started} před delší dobou, než je jeho interval, podle historie běhů. Synchronizace spuštěná ručně tedy odsune další automatickou a krok, který opakovaně selhává, se opakuje ve svém intervalu, ne při každém tiku. Přehled obchodu zobrazuje u každého kroku poslední běh, příští termín a důvod blokace, pokud je blokován. První odeslání katalogu spusťte ručně — nejprve pomocí {dryRun} — než jej zařadíte do plánu.',
'Shopify_G_Started_Lower' => 'spustil',
'Shopify_G_Where_Setting' => 'Kde se nachází jednotlivá nastavení',
'Shopify_G_Where_Setting_Note' => 'Všechna jsou u existujícího obchodu: {path}, poté tužka (nebo {edit} na vlastní stránce obchodu).',
'Shopify_G_Product_Images' => 'Obrázky produktů',
'Shopify_G_Img_1' => 'Obrázky odcházejí s produktem při {push} — nejprve hlavní obrázek, pak galerie, pak jeden pro každou variantu, která má vlastní, až padesát.',
'Shopify_G_Products_Push' => 'odeslání produktů',
'Shopify_G_Img_2' => 'Obrázek varianty se nahraje s produktem a poté {assigned}, což odpovídá modelu Shopify: varianta odkazuje na jeden z obrázků produktu. Varianta používající hlavní obrázek jej nenahrává dvakrát.',
'Shopify_G_Assigned' => 'přiřadí k této variantě',
'Shopify_G_Img_3' => 'Obrázek uložený jako soubor se do Shopify {uploaded}, nikoli propojí, takže funguje i tehdy, když tato instalace není dosažitelná z internetu. Obrázek přidaný jako vložený odkaz se předá Shopify jako tato URL, která musí být veřejně dosažitelná.',
'Shopify_G_Uploaded' => 'nahraje',
'Shopify_G_Img_4' => 'Znovu se odesílají, pouze když se skutečně změní — odeslání, které mění pouze cenu, nechá obrázky obchodu beze změny, protože jejich odesláním se nahradí celá sada.',
'Shopify_G_Img_5' => 'Po odebrání obrázku v ERP {not} obrázek v Shopify smazán. Smažte jej i tam, jinak jej obchod bude stále zobrazovat.',
'Shopify_G_Commands' => 'Užitečné příkazy',
'Shopify_G_Command_Copied' => 'Příkaz zkopírován',
'Shopify_G_Foot' => 'Každá synchronizace zapisuje do {logs} a Přehled každého obchodu ukazuje, kdy každý krok naposledy proběhl, kdy je příště na řadě a co jej blokuje, pokud něco. Tam se podívejte nejdříve, když synchronizace neudělala, co jste čekali.',
'Shopify_G_Covers' => 'Zahrnuje',
'Shopify_G_Covers_Rt' => 'Objednávky a úpravy provedené v Shopify; zásoby odcházející z ERP (prodej v POS, vratka, úprava)',
'Shopify_G_Covers_Sch' => 'Vše v obou směrech — včetně odesílání katalogu a všeho, co rychlá cesta vynechala',
'Shopify_G_Speed' => 'Rychlost',
'Shopify_G_Speed_Rt' => 'Sekundy',
'Shopify_G_Speed_Sch' => 'Interval kroku (5 minut až 7 dní)',
'Shopify_G_Needs' => 'Potřebuje',
'Shopify_G_Needs_Rt' => 'Veřejná adresa HTTPS a podpisový klíč pro příchozí webhooky. Odchozí zásoby nepotřebují vůbec nic',
'Shopify_G_Needs_Sch' => 'Záznam cronu spouštějící {cmd}',
'Shopify_G_Switched_On_At' => 'Zapíná se v',
