'Shopify_G_Set_Credentials_What' => 'Přihlašovací údaje z aplikace Shopify (Dev Dashboard nebo starší vlastní aplikace).',
'Shopify_G_Set_Targets' => 'Sklad ERP, umístění Shopify',
'Shopify_G_Set_Targets_What' => 'Jaké zásoby tento obchod prodává a kam se zakládají objednávky.',
'Shopify_G_Set_Price_What' => 'Maloobchodní, velkoobchodní nebo minimální cena.',
'Shopify_G_Set_Create_Missing' => 'Vytvářet chybějící produkty / zákazníky',
'Shopify_G_Set_Create_Missing_What' => 'Zda smí načtení vytvářet záznamy ERP, které nedokáže spárovat.',
'Shopify_G_Set_Entities' => 'Které entity se vůbec synchronizují',
'Shopify_G_Set_Entities_What' => 'Vypnuto zde znamená vypnuto všude — ručně, podle plánu i přes webhook.',
