'Cr_Guide_Step_Account' => 'Přidejte kurýrní účet',
'Cr_Guide_Step_Account_Help' => 'Vyberte kurýra a vložte API klíče z jeho administrace. Účtů může být i více, například jeden pro každý sklad.',
'Cr_Guide_Step_Test' => 'Otestujte připojení',
'Cr_Guide_Step_Test_Help' => 'Otestovat připojení ověří klíče a často vypíše kódy, které vyžadují možnosti kurýra.',
'Cr_Guide_Step_Webhook' => 'Zaregistrujte URL webhooku',
'Cr_Guide_Step_Webhook_Help' => 'Kurýři, kteří aktualizace sami odesílají, potřebují URL webhooku účtu (uvedenou níže), aby se stavy měnily okamžitě. Ostatní jsou kontrolováni podle plánu.',
'Cr_Guide_Step_Cod' => 'Zvolte, kam půjdou výplaty dobírek',
'Cr_Guide_Step_Cod_Help' => 'V Nastavení kurýrů vyberte účet, na který se zaznamenávají výplaty dobírek, a určete, jak se zachází s vrácenými zásilkami a poplatky kurýra.',
'Cr_Guide_Step_Notify' => 'Informujte zákazníky',
'Cr_Guide_Step_Notify_Help' => 'SMS, e-mail nebo WhatsApp při zvolených stavech, s odkazem na stránku sledování.',
'Cr_Guide_Step_Book' => 'Podejte první objednávku',
