'Cr_Guide_Meaning' => 'Význam',
'Cr_Guide_T_Statuses' => 'Stavy',
'Cr_Guide_Statuses_Note' => 'Stavy se posouvají pouze vpřed, takže opožděná aktualizace nikdy nevrátí zásilku zpět. U doručené zásilky lze stále nahlásit, že se vrací nebo byla vrácena.',
'Cr_Guide_S_booked' => 'Kurýr má objednávku; zatím ji nikdo nevyzvedl. Podání lze zrušit pouze v tomto stavu.',
'Cr_Guide_S_picked_up' => 'Kurýr zásilku vyzvedl.',
'Cr_Guide_S_in_transit' => 'Přesouvá se mezi depy, je v celním řízení nebo je pozdržena.',
'Cr_Guide_S_out_for_delivery' => 'Dnes u doručovatele.',
'Cr_Guide_S_failed_attempt' => 'Zákazník nebyl doma, zásilku odmítl nebo je chybná adresa. Kurýr to zkusí znovu, nebo ji vrátí.',
'Cr_Guide_S_delivered' => 'Předáno zákazníkovi. Částka dobírky přejde do stavu Vybráno kurýrem.',
'Cr_Guide_S_returning' => 'Na cestě zpět k vám.',
'Cr_Guide_S_returned' => 'Zpět u vás: čeká ve Vratkách ke kontrole, nebo je automaticky naskladněna.',
'Cr_Guide_S_cancelled' => 'Podání bylo zrušeno.',
'Cr_Guide_T_Booking' => 'Podávání objednávek',
'Cr_Guide_B_Booking' => 'Odeslat kurýrovi předvyplní formulář z prodeje: příjemce, adresu, dosud dlužnou částku jako dobírku a hmotnost produktů. Kurýři s vlastním seznamem měst zobrazí výběr a vaše volba se pro dané město zapamatuje. Agregátory, DHL, FedEx, UPS a Lalamove nabízejí Porovnat ceny: vyberte cenu a tlačítkem Podat ji zakoupíte. Více prodejů lze podat najednou ze seznamu prodejů.',
'Cr_Guide_T_Cod' => 'Dobírka',
'Cr_Guide_B_Cod' => 'Dobírková zásilka přechází ze stavu Nevybráno přes Vybráno kurýrem (při doručení) do stavu Vyplaceno vám. Kurýři, kteří hlásí výplaty, posunou poslední krok sami; u ostatních použijte Aktualizovat dobírku. Je-li v Nastavení kurýrů zvolen účet, výplata se zaznamená jako platba k prodeji. Poplatky kurýra lze po dokončení zásilky uložit jako náklad.',
'Cr_Guide_T_Returns' => 'Vrácené zásilky',
'Cr_Guide_B_Returns' => 'Ve výchozím stavu vrácená zásilka čeká v Kurýrních zásilkách v části Vratky ke kontrole. Naskladnit vytvoří vratku prodeje pro celou objednávku a vrátí položky na sklad; Vyřadit nic nevrací, slouží pro poškozené nebo ztracené zásilky. V Nastavení kurýrů lze místo toho zapnout automatické naskladnění.',
'Cr_Guide_T_Customers' => 'Zprávy zákazníkům a stránka sledování',
'Cr_Guide_B_Customers' => 'Oznámení zákazníkům v Nastavení kurýrů odesílají SMS, e-mail nebo WhatsApp při zaškrtnutých stavech, každé jednou na zásilku, s vaším vlastním textem. Stránka sledování ve vašem online obchodě umožňuje zákazníkům sledovat zásilku podle sledovacího čísla nebo podle čísla objednávky a telefonu. Zákazníci, kteří často vracejí zásilky, dostanou při podání odznak rizika vrácení.',
'Cr_Guide_T_Labels' => 'Štítky',
'Cr_Guide_B_Labels' => 'Tisk štítku poskytne vlastní štítek kurýra, pokud jej vydává (PDF, odkaz nebo obrázek), jinak štítek Stocky se sledovacím čárovým kódem a částkou k vybrání. Pro tisk povolte pro tento web vyskakovací okna. DHL, FedEx a UPS poskytují štítek pouze jednou, při podání, a Stocky jej uchovává pro opakovaný tisk.',
'Cr_Guide_T_Faq' => 'Řešení problémů',
'Cr_Guide_Q_Test' => 'Test připojení selhává',
'Cr_Guide_A_Test' => 'Testovací klíče patří k Testovacímu režimu a ostré klíče k Ostrému režimu; jsou odlišné. Otevřete Protokoly kurýrů a přečtěte si odpověď kurýra s přesným důvodem.',
'Cr_Guide_Q_City' => 'Kurýr odmítá město nebo adresu',
'Cr_Guide_A_City' => 'Vyberte město ze seznamu měst kurýra ve formuláři podání; kurýři přijímají pouze své vlastní názvy. Kurýři pracující s poštovními adresami navíc potřebují kraj, PSČ a dvoupísmenný kód země.',
'Cr_Guide_Q_Webhook' => 'Stavy se samy nemění',
'Cr_Guide_A_Webhook' => 'U kurýrů, kteří aktualizace odesílají sami, ověřte, že je URL webhooku u kurýra zaregistrována: Protokoly kurýrů zobrazují každou přijatou aktualizaci nebo důvod jejího odmítnutí (například chybný tajný klíč). Ostatní kurýři jsou kontrolováni podle plánu v Nastavení kurýrů a Zkontrolovat stav nyní se dotáže okamžitě.',
'Cr_Guide_Q_Stuck' => 'Zásilka zobrazuje chybu kontroly stavu',
'Cr_Guide_A_Stuck' => 'Kurýr odmítl poslední kontroly; důvod je uveden u zásilky a v Protokolech kurýrů. Po opakovaných selháních se zásilka přestane automaticky kontrolovat: odstraňte příčinu a poté použijte Zkontrolovat stav nyní.',
'Cr_Guide_Q_Label' => 'Při tisku štítku se nic neotevře',
'Cr_Guide_A_Label' => 'Váš prohlížeč zablokoval vyskakovací okno. Povolte pro tento web vyskakovací okna a zkuste to znovu.',
'Cr_Guide_Q_Cod' => 'Výplata dobírky nebyla zaznamenána k prodeji',
'Cr_Guide_A_Cod' => 'V Nastavení kurýrů musí mít dobírka zapnutý přepínač a zvolený účet. Bez účtu jsou výplaty pouze označeny jako vyplacené.',
