'Tfa_Guide_Lead' => 'Dvoufázové ověření (2FA) přidává k přihlášení druhý krok: po zadání hesla zaměstnanci zadají 6místný kód z ověřovací aplikace v telefonu. Ukradené nebo uhodnuté heslo pak k přihlášení nestačí.',
