'Tfa_Guide_App_Title' => 'Nainstalujte ověřovací aplikaci',
'Tfa_Guide_App_Text' => 'Funguje jakákoli aplikace podporující standardní 6místné kódy (TOTP). Jsou zdarma a fungují offline:',
'Tfa_Guide_Enable_Title' => 'Zapněte jej v profilu',
'Tfa_Guide_Enable_1' => 'Otevřete Profil (nabídka avatara vpravo nahoře) a najděte kartu „Dvoufázové ověření“.',
'Tfa_Guide_Enable_2' => 'Klikněte na „Zapnout“ a potvrďte současným heslem.',
