'Tfa_Guide_Enable_4' => 'Pro dokončení zadejte 6místný kód zobrazený v aplikaci.',
'Tfa_Guide_Open_Profile' => 'Otevřít můj profil',
'Tfa_Guide_Codes_Title' => 'Uložte si záložní kódy',
'Tfa_Guide_Codes_Text' => 'Ihned po nastavení se jednou zobrazí 8 záložních kódů. Každý z nich jednorázově nahradí kód z telefonu — při ztrátě, poškození nebo resetu telefonu. Stáhněte si je nebo zkopírujte a uchovejte na bezpečném místě mimo telefon.',
'Tfa_Guide_Codes_Note' => 'Dochází vám? Volba „Nové záložní kódy“ v profilu nahradí celou sadu; staré kódy přestanou fungovat.',
'Tfa_Guide_Signin_Title' => 'Přihlašování',
'Tfa_Guide_Signin_Text' => 'Po zadání e-mailu a hesla přihlašovací stránka vyžádá aktuální kód z aplikace. Kódy se mění každých 30 sekund a každý funguje pouze jednou.',
'Tfa_Guide_Signin_Trust' => 'Zaškrtnutím „Na tomto zařízení se znovu neptat“ se v daném prohlížeči kód :days dní nevyžaduje.',
'Tfa_Guide_Signin_Recovery' => 'Nemáte telefon po ruce? Klikněte na „Použít záložní kód“ a zadejte jeden z uložených kódů.',
'Tfa_Guide_Admin_Title' => 'Pro správce',
'Tfa_Guide_Require_Title' => 'Nastavte jej jako povinné',
'Tfa_Guide_Require_Text' => 'Na této kartě zapněte „Vyžadovat dvoufázové ověření“ a vyberte role, které jej musí používat — nebo seznam ponechte prázdný pro všechny uživatele. Uložte kliknutím na Odeslat.',
'Tfa_Guide_Require_Next' => 'Nikdo nebude odhlášen. Uživatelé, kteří 2FA ještě nemají, budou při příštím přihlášení na přihlašovací stránce provedeni nastavením, než se dostanou dovnitř, a tam uvidí i své záložní kódy.',
'Tfa_Guide_Require_Note' => 'Uživatelé, pro které je vyžadováno, jej nemohou ve svém profilu vypnout.',
'Tfa_Guide_Trust_Title' => 'Důvěryhodná zařízení',
'Tfa_Guide_Trust_Text' => 'Volba „Pamatovat si důvěryhodná zařízení“ určuje, jak dlouho může prohlížeč po úspěšném přihlášení přeskočit kód. U sdílených nebo veřejných počítačů, jako je POS na prodejně, zvolte „Vždy vyžadovat kód“.',
'Tfa_Guide_Trust_Note' => 'Snížení počtu dní zkrátí platnost i již důvěryhodným zařízením; vypnutím nebo resetováním 2FA se zapomenou všechna.',
'Tfa_Guide_Lost_Title' => 'Ztracený telefon a žádné záložní kódy',
'Tfa_Guide_Lost_Text' => 'Na stránce Uživatelé mají uživatelé s 2FA ve sloupci 2FA hodnotu „Zapnuto“. Tlačítko se štítem v Akcích jej resetuje: uživatel se přihlásí pouze heslem a aplikaci si nastaví znovu (nebo k tomu bude vyzván, pokud je vyžadováno).',
'Tfa_Guide_Lost_Warn' => 'Před resetem ověřte, kdo o to žádá — reset odstraní ochranu, kterou 2FA danému účtu poskytuje.',
'Tfa_Guide_Open_Users' => 'Otevřít Uživatele',
'Tfa_Guide_Mobile_Title' => 'Mobilní aplikace a API',
'Tfa_Guide_Mobile_Text' => 'Mobilní aplikace i koncový bod API pro tokeny vyžadují stejný kód. Pokud je 2FA vyžadováno u uživatele, který jej ještě nenastavil, musí se k tomu jednou přihlásit přes web.',
'Tfa_Guide_Protect_Title' => 'Vestavěná ochrana',
'Tfa_Guide_Protect_1' => '5 chybných kódů zablokuje zadávání kódů pro daného uživatele na 15 minut, bez ohledu na výše uvedené nastavení zámku.',
'Tfa_Guide_Protect_2' => 'Každý kód i každý záložní kód funguje pouze jednou.',
'Tfa_Guide_Protect_3' => 'Při zapnuté volbě „Zaznamenávat aktivitu přihlášení“ se chybné kódy zobrazí v seznamu Aktivita přihlášení jako „Chybný kód 2FA“.',
'Tfa_Guide_Trouble_Title' => 'Řešení problémů',
'Tfa_Guide_Faq_Clock_Q' => '„Tento kód není platný“ u čerstvého kódu',
'Tfa_Guide_Faq_Clock_A' => 'Hodiny v telefonu pravděpodobně nejdou přesně. Kódy závisí na čase: nastavte datum a čas v telefonu na automatické (čas ze sítě) a zkuste další kód.',
'Tfa_Guide_Faq_Phone_Q' => 'Přechod na nový telefon',
'Tfa_Guide_Faq_Phone_A' => 'Použijte vlastní funkci přenosu v ověřovací aplikaci, nebo v profilu 2FA vypněte a znovu zapněte s novým telefonem (pokud je vyžadováno, požádejte místo toho správce o reset).',
'Tfa_Guide_Faq_Locked_Q' => '„Příliš mnoho neplatných kódů“',
'Tfa_Guide_Faq_Locked_A' => 'Počkejte zobrazenou dobu (až 15 minut), nebo požádejte správce o reset 2FA uživatele.',
'Tfa_Guide_Faq_Key_Q' => 'Po přesunu serveru se nikdo s 2FA nemůže přihlásit',
'Tfa_Guide_Faq_Key_A' => 'Tajné klíče 2FA jsou šifrovány pomocí APP_KEY v souboru .env. Při přesunu nebo obnově aplikace zachovejte stejný APP_KEY; pokud se změnil, musí správce bez 2FA resetovat dotčené uživatele.',
'Tfa_Guide_Button' => 'Návod',
'Tfa_Guide_Title' => 'Návod k dvoufázovému ověření',
'Sec_2fa_Pending' => 'Ještě nenastaveno: :count',
'Sec_2fa_See_Who' => 'Zobrazit koho',
'Sec_2fa_Grace_Off' => 'Žádná — nastavit při příštím přihlášení',
'Sec_2fa_Applied' => 'Odhlášeno uživatelů: :count.',
'Tfa_Guide_Rollout_Title' => 'Zavedení pro všechny uživatele',
'Tfa_Guide_Rollout_1' => 'Nejprve jej zapněte pro svůj vlastní účet (Profil), abyste znali postup.',
'Tfa_Guide_Rollout_2' => 'Sdělte týmu, kterou aplikaci si mají nainstalovat a že nastavení při přihlášení zabere minutu.',
'Tfa_Guide_Rollout_3' => 'Zapněte „Vyžadovat dvoufázové ověření“, pole „Vyžadováno pro“ ponechte prázdné (= všichni uživatelé) a případně zvolte přechodné období. Klikněte na Odeslat.',
'Tfa_Guide_Rollout_4' => 'Klikněte na „Odhlásit uživatele bez 2FA“, aby si jej již přihlášení uživatelé nastavili hned, a ne až při některém pozdějším přihlášení. Vy zůstanete přihlášeni.',
'Tfa_Guide_Rollout_5' => 'Postup sledujte pomocí počítadla na této kartě nebo filtru „Vyžaduje nastavení“ na stránce Uživatelé.',
'Tfa_Guide_Rollout_Note' => 'Při přechodném období zobrazuje obrazovka nastavení až do termínu volbu „Připomenout později“; poté je nastavení pro přihlášení povinné.',
'Tfa_Guide_Customers_Title' => 'Zákaznické účty (obchod a klientský portál)',
'Tfa_Guide_Customers_Text' => 'Zákazníci mohou chránit i své vlastní účty. Pro každého zákazníka je to volitelné a nikdy vynucené: zapněte to v Nastavení obchodu → Řízení přístupu k registraci (online obchod) a v Klientský portál → Nastavení portálu (klientský portál).',
'Tfa_Guide_Customers_1' => 'Zákazníci si jej zapínají v sekci Můj účet (obchod) nebo Profil (portál).',
'Tfa_Guide_Customers_2' => 'Zvolí kód zasílaný e-mailem — nejjednodušší, bez aplikace — nebo ověřovací aplikaci se záložními kódy.',
'Tfa_Guide_Customers_3' => 'Kódy zasílané e-mailem vyžadují funkční nastavení pošty (Nastavení → Nastavení pošty). Platnost vyprší po 10 minutách.',
'Tfa_Guide_Customers_4' => 'Pozdějším vypnutím této volby se zastaví nová nastavení; zákazníci, kteří jej již používají, budou o kód nadále žádáni a mohou si jej sami vypnout.',
'Tfa_Required_Grace_Notice' => 'Váš správce vyžaduje dvoufázové ověření. Při přihlášení jej můžete odložit do :date; poté bude nastavení povinné.',
'Tfa_Filter_All' => '2FA: všichni uživatelé',
