'Store_Customer_2fa' => 'Dvoufázové ověření',
'Store_Customer_2fa_Help' => 'Umožňuje zákazníkům chránit účet kódem zaslaným e-mailem nebo z ověřovací aplikace; zapíná se v sekci Můj účet. Pro každého zákazníka volitelné.',
'Portal_2fa' => 'Dvoufázové ověření',
'Portal_2fa_Help' => 'Umožňuje klientům chránit přihlášení do portálu kódem zaslaným e-mailem nebo z ověřovací aplikace; zapíná se v jejich profilu. Pro každého klienta volitelné.',
