'Two_factor_remind_later' => 'Připomenout později',
'Sec_2fa_Grace' => 'Přechodné období',
'Sec_2fa_Grace_Help' => 'Umožňuje uživatelům na obrazovce nastavení zvolit „Připomenout později“ až do termínu, aby nikdo nebyl zastaven uprostřed směny. Počítá se od okamžiku zapnutí požadavku.',
'Sec_2fa_Grace_Ends' => 'Nastavení bude povinné od :date.',
'Sec_2fa_Apply' => 'Použít nyní',
'Sec_2fa_Apply_Help' => 'Již přihlášení uživatelé jsou vyzváni až při příštím přihlášení, což může být s volbou „Zapamatovat si mě“ za několik měsíců. Tímto se na všech zařízeních odhlásí všichni, kdo musí nastavit 2FA a dosud tak neučinili, takže si jej nastaví při opětovném přihlášení. Vy zůstanete přihlášeni.',
